Float a = 1 - 2 * u[0];
Float b = 1 - 2 * u[1];
Float r = std::sqrt(a * a + b * b);
if (r > 1) {
    Float theta = 2 * Pi * u[1];
    Float radius = std::sqrt(u[0]);
    return Point2f(radius * std::cos(theta), radius * std::sin(theta));
}
Float rho = 1 / std::sqrt(1 - r * r);
return Point2f(a * rho, b * rho);

